//! The leading-zero vectors of dcr-rs (`tests/vectors.rs`), which its
//! authors generated by running dcrd's hdkeychain v3 with `Child` and
//! `ChildBIP32Std`. Every string here is also re-checked against the Go
//! oracle by `oracle_diff`/`frozen` (the seeds are in the frozen vectors).

use purse_hdkeychain::{ExtendedKey, HdVersions};
use purse_testutil::unhex;

const H: u32 = 0x8000_0000;

/// dcrd's BIP32 test-vector-4 seed. m/0' has private key `00d948e9…`, so
/// m/0'/1' is where the variants part company.
const ZERO_LEAD_SEED_A: &str = "3ddd5602285899a946114506157c7997e5444528f3003f6134712147db19b678";

/// A seed whose m/44'/42' private key is `0043cf2d…`, so the divergence
/// lands on the BIP44 account key.
const ZERO_LEAD_SEED_B: &str = "2fb78f0f7770720fa05952587c055866852c1e2f2cd7814e92e06d91b72af083";

/// A seed whose master private key begins with `0x00`.
const ZERO_LEAD_MASTER_SEED: &str =
    "de8ed51864182c52cc0205cd0ec55fa236a48c2bce8e9994c69ab44ae31ebb5e";

fn master(seed: &str) -> ExtendedKey {
    ExtendedKey::new_master(&unhex(seed), &HdVersions::MAINNET).expect("master")
}

fn derive(k: &ExtendedKey, path: &[u32], strict: bool) -> ExtendedKey {
    path.iter().fold(k.clone(), |k, &i| {
        if strict {
            k.child_bip32_std(i)
        } else {
            k.child(i)
        }
        .expect("child")
    })
}

/// A mainnet pay-to-pubkey-hash address (network ID `07 3f`).
fn p2pkh(pub_key: &[u8]) -> String {
    let hash = dcroxide_crypto::ripemd160::sum160(&dcroxide_crypto::blake256::sum256(pub_key));
    dcroxide_base58::check_encode(&hash, [0x07, 0x3f])
}

#[test]
fn hardened_derivation_matches_dcrd_legacy_child() {
    // (seed, path, dcrd Child, dcrd ChildBIP32Std)
    let cases: &[(&str, &[u32], &str, &str)] = &[
        (
            ZERO_LEAD_SEED_A,
            &[H, 1 | H],
            "dprv3mhK5vAEzovJTfnqwfzGTamym6yPPGEggq5fpQHrnXGyb22Doqew7Co7mCvYHe6nTCewnggesjM4LVJj8RFJ92ANtogs3NY7ev4YxSwf6ez",
            "dprv3mhK5vAEzovJUV5RycwKGbth8MYtoYL1aJTxN1T8PLmH6da6aMU8nYKQiC5Zj7mC7pH4G8xPxGZVR51FG9Ssptzx1c39A1JxADS6zDrsLPr",
        ),
        (
            ZERO_LEAD_SEED_B,
            &[44 | H, 42 | H, H],
            "dprv3o9RD4HnZWi2Ammh2RMH2yLR2oQzt8iHLk8eEhzP53xMffriXxWUpiFoJKQ927i6g1V1zraGeE1FKXxcuKXZg5WWUK6Nc3nVtdFBPHoStQ4",
            "dprv3o9RD4HnZWi2BfE3uRFunUsF9hiDyykGeDZfjr8McYm7pv2bTCYUfsnM6XmywQDTXrjcizDorH6YimQhaLBWgFWabQh59PuSxunuoZqAZQU",
        ),
    ];
    for (seed, path, want_legacy, want_strict) in cases {
        let m = master(seed);
        assert_eq!(
            *derive(&m, path, false).string(),
            *want_legacy,
            "Child {path:?}"
        );
        assert_eq!(
            *derive(&m, path, true).string(),
            *want_strict,
            "ChildBIP32Std {path:?}"
        );
        assert_ne!(want_legacy, want_strict);
    }
}

/// A leading zero at the end of the path serializes the same under both
/// variants: the string pads the stored key to 32 bytes.
#[test]
fn leading_zero_key_serializes_identically_under_both_variants() {
    const WANT: &str = "dprv3jkqwzsd88yXqZJdSuLnfKqGPYzCVffataF79tcuPhdudeU3d1uUpvwn5Btmbai3BoVYhzbsEQ7tcH1XtEJ1BhzNSAtZfqv8BtSpdq5FEpj";
    let m = master(ZERO_LEAD_SEED_A);
    let legacy = derive(&m, &[H], false);
    let strict = derive(&m, &[H], true);
    assert_eq!(*legacy.string(), WANT);
    assert_eq!(*strict.string(), WANT);
    assert_eq!(legacy.serialized_priv_key().expect("private").len(), 31);
    assert_eq!(strict.serialized_priv_key().expect("private").len(), 32);
}

#[test]
fn wallet_path_matches_dcrwallet_for_a_leading_zero_seed() {
    let m = master(ZERO_LEAD_SEED_B);
    let account = derive(&m, &[44 | H, 42 | H, H], false);
    assert_eq!(
        *account.neuter().string(),
        "dpubZEwWaBr5dtmp5BfTGwQdZC8feoyGK5JMYHkxycvk58YzPDtMQur5uHmpT2CxorMxmQezrnzrb9Ki5Dq4cfStQtPrHc1eeFqHdKtnyy4pttK"
    );
    let addr = derive(&account, &[0, 0], false);
    assert_eq!(
        p2pkh(addr.serialized_pub_key()),
        "DsSYaeDjG6LYn1KJ85bNu1ousCu74scVVUC"
    );

    let strict = derive(&m, &[44 | H, 42 | H, H], true);
    let strict_addr = derive(&strict, &[0, 0], false);
    assert_eq!(
        p2pkh(strict_addr.serialized_pub_key()),
        "DsgSmj1YRrxL2m4yPtkZmm5uZVP5Bis9Gbb"
    );

    // Public derivation below the account is variant-independent.
    let via_pub = derive(&account.neuter(), &[0, 0], false);
    assert_eq!(
        p2pkh(via_pub.serialized_pub_key()),
        "DsSYaeDjG6LYn1KJ85bNu1ousCu74scVVUC"
    );
}

/// The master key is never stripped.
#[test]
fn master_key_leading_zero_is_not_stripped() {
    const DCRD_BOTH: &str = "dprv3oRKZopwMRqrhixpAEVhipabqeQycvoLBqnFZtJm82vzJk2qcntNWoQkDVBYMXWqVBNqf8pRopzHXPQCywoiD47A7fBa2XRVpvg4QAdqqcE";
    let m = master(ZERO_LEAD_MASTER_SEED);
    let key = m.serialized_priv_key().expect("private");
    assert_eq!(key.len(), 32);
    assert_eq!(key[0], 0);
    let path = [44 | H, 42 | H, H];
    assert_eq!(*derive(&m, &path, false).string(), DCRD_BOTH);
    assert_eq!(*derive(&m, &path, true).string(), DCRD_BOTH);
}

/// Mixing the variants: `strict` decides how the child is stored, the
/// preimage comes from how the parent is stored.
#[test]
fn mixed_variant_path_matches_dcrd() {
    let m = master("667c017d055e9d57ab3374a9d49b061e4f5de2c2a767896b67d59b5d6eeeca33");
    let k = m
        .child(44 | H)
        .and_then(|k| k.child_bip32_std(42 | H))
        .and_then(|k| k.child(H))
        .and_then(|k| k.child(0))
        .expect("path");
    assert_eq!(
        *k.string(),
        "dprv3pwGQJQ6fWTjdwJnwfa1MqfvdY38tm4nyFYHtttrSvcRjB3vfhiJmPBtWqqgJY8qVKMZMVkNDbs6wzsYjLUCrcF6TUatpwfsVt6RBtp199g"
    );
}

/// Serializing and reparsing restores the padded form and changes the
/// hardened children, as in dcrd.
#[test]
fn base58_round_trip_restores_the_padded_form() {
    let net = HdVersions::MAINNET;
    let m = master(ZERO_LEAD_SEED_B);
    let parent = derive(&m, &[44 | H, 42 | H], false);
    assert!(parent.serialized_priv_key().expect("private").len() < 32);
    let direct = parent.child(H).expect("child");

    let reparsed = ExtendedKey::new_key_from_string(&parent.string(), &net).expect("parse");
    assert_eq!(reparsed.serialized_priv_key().expect("private").len(), 32);
    let after_round_trip = reparsed.child(H).expect("child");
    assert_ne!(*direct.string(), *after_round_trip.string());
    assert_eq!(
        *after_round_trip.string(),
        *derive(&m, &[44 | H, 42 | H, H], true).string()
    );

    // A strict child of a stripped parent still sees the stripped parent.
    assert_eq!(
        *parent.child_bip32_std(H).expect("child").string(),
        *direct.string()
    );
}
